import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:path_provider/path_provider.dart';

import 'take.dart';
import 'take_store.dart';

Future<TakeStore?> openTakeStore() async {
  final docs = await getApplicationDocumentsDirectory();
  return FileTakeStore(Directory('${docs.path}/takes'));
}

class FileTakeStore implements TakeStore {
  final Directory dir;
  FileTakeStore(this.dir);

  File _json(String id) => File('${dir.path}/$id.json');

  // Ids are generated by TakeStore.newId; refuse anything that could
  // reach outside the folder.
  static bool _safe(String name) => RegExp(r'^[A-Za-z0-9._-]+$').hasMatch(name) &&
      !name.startsWith('.');

  @override
  Future<void> save(Take take, Uint8List? wav) async {
    if (!_safe(take.id)) throw ArgumentError.value(take.id, 'take.id');
    await dir.create(recursive: true);
    if (wav != null && take.audioFile != null) {
      if (!_safe(take.audioFile!)) {
        throw ArgumentError.value(take.audioFile, 'take.audioFile');
      }
      await File('${dir.path}/${take.audioFile}').writeAsBytes(wav, flush: true);
    }
    // JSON last: a take is listed only once its audio is on disk.
    final tmp = File('${dir.path}/${take.id}.json.tmp');
    await tmp.writeAsString(take.toJson(), flush: true);
    await tmp.rename(_json(take.id).path);
  }

  @override
  Future<List<TakeSummary>> list() async {
    if (!await dir.exists()) return [];
    final out = <TakeSummary>[];
    await for (final f in dir.list()) {
      if (f is! File || !f.path.endsWith('.json')) continue;
      try {
        // Only the header is needed, but takes are small enough to parse.
        final m = jsonDecode(await f.readAsString()) as Map<String, dynamic>;
        final t = (m['t'] as List);
        out.add((
          id: m['id'] as String,
          title: m['title'] as String,
          started: DateTime.parse(m['started'] as String).toLocal(),
          durationMs: t.isEmpty ? 0 : (t.last as num).toInt(),
        ));
      } catch (_) {
        // A damaged file: leave it out rather than fail the whole list.
      }
    }
    out.sort((a, b) => b.started.compareTo(a.started));
    return out;
  }

  @override
  Future<Take?> load(String id) async {
    if (!_safe(id)) return null;
    final f = _json(id);
    if (!await f.exists()) return null;
    return Take.fromJson(await f.readAsString());
  }

  @override
  Future<String?> audioPath(Take take) async {
    final name = take.audioFile;
    if (name == null || !_safe(name)) return null;
    final f = File('${dir.path}/$name');
    return await f.exists() ? f.path : null;
  }

  @override
  Future<void> delete(String id) async {
    if (!_safe(id)) return;
    final take = await load(id);
    final audio = take?.audioFile;
    if (audio != null && _safe(audio)) {
      final f = File('${dir.path}/$audio');
      if (await f.exists()) await f.delete();
    }
    final j = _json(id);
    if (await j.exists()) await j.delete();
  }
}
